    "dependencies": [],
    "order": 20,
    "folderPath": "/home/edvins/features-for-web/web-for-options/features/oklch-ambient-glow-hero",
    "relativePath": "features/oklch-ambient-glow-hero",
    "previewUrl": "features/oklch-ambient-glow-hero/index.html",
    "liveSiteUrl": null,
